local PlantLabelMaker = {}
local PRODUCTS = {
    iron_plantlabel = { name = "Železni oznaka za rastline", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni oznaka za rastline za vrtnarje." },
    bronze_plantlabel = { name = "Bronast oznaka za rastline", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast oznaka za rastline za vrtnarje." },
    silver_plantlabel = { name = "Srebrn oznaka za rastline", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn oznaka za rastline za vrtnarje." },
    gilded_plantlabel = { name = "Pozlačen oznaka za rastline", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen oznaka za rastline za vrtnarje." },
    jewel_set_plantlabel = { name = "Draguljast oznaka za rastline", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast oznaka za rastline za vrtnarje." },
    royal_sovereign_plantlabel = { name = "Kraljevski suveren oznaka za rastline", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren oznaka za rastline z biseri za krono." },
}
local BUILDINGS = {
    plantlabel_workshop = { name = "Plantlabel delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    plantlabel_house = { name = "Plantlabel hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_plantlabel_atelier = { name = "Mojstrski plantlabel atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_plantlabel_palace = { name = "Suverena plantlabel palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
PlantLabelMaker.ironStock=12; PlantLabelMaker.bronzeStock=10; PlantLabelMaker.woodStock=16; PlantLabelMaker.leatherStock=10; PlantLabelMaker.silverStock=8; PlantLabelMaker.goldStock=6; PlantLabelMaker.jewelStock=4; PlantLabelMaker.pearlStock=4
PlantLabelMaker.productStock = {}; PlantLabelMaker.buildings = {}; PlantLabelMaker.maker = nil; PlantLabelMaker.activeMaking = {}; PlantLabelMaker.totalProducts = 0; PlantLabelMaker.dayTimer = 0
function PlantLabelMaker.init() PlantLabelMaker.ironStock=12; PlantLabelMaker.bronzeStock=10; PlantLabelMaker.woodStock=16; PlantLabelMaker.leatherStock=10; PlantLabelMaker.silverStock=8; PlantLabelMaker.goldStock=6; PlantLabelMaker.jewelStock=4; PlantLabelMaker.pearlStock=4; PlantLabelMaker.productStock={}; PlantLabelMaker.buildings={}; PlantLabelMaker.maker=nil; PlantLabelMaker.activeMaking={}; PlantLabelMaker.totalProducts=0; PlantLabelMaker.dayTimer=0; print("[PlantLabelMaker] Royal Plant Label Maker System initialized (6 products, 4 buildings)") end
function PlantLabelMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlantLabelMaker.maker={name=n or ("Oznakar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oznakar najet: %s (spretnost: %d)",PlantLabelMaker.maker.name,s),"success") end; return true end
function PlantLabelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlantLabelMaker.build(id) local ok,e=PlantLabelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlantLabelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlantLabelMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlantLabelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlantLabelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PlantLabelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PlantLabelMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PlantLabelMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PlantLabelMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PlantLabelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlantLabelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlantLabelMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlantLabelMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlantLabelMaker.buildings==0 then return false,"Potrebna oznakarska delavnica" end; if not PlantLabelMaker.maker then return false,"Potreben oznakar" end; return true end
function PlantLabelMaker.make(pt,qty) qty=qty or 1; local ok,e=PlantLabelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PlantLabelMaker.ironStock=PlantLabelMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PlantLabelMaker.bronzeStock=PlantLabelMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PlantLabelMaker.woodStock=PlantLabelMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PlantLabelMaker.leatherStock=PlantLabelMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PlantLabelMaker.silverStock=PlantLabelMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlantLabelMaker.goldStock=PlantLabelMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlantLabelMaker.jewelStock=PlantLabelMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlantLabelMaker.pearlStock=PlantLabelMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlantLabelMaker.maker then t=math.max(1,t-math.floor(PlantLabelMaker.maker.skill/13)) end; table.insert(PlantLabelMaker.activeMaking,{id="plantlabel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlantLabelMaker.completeMaking(m) local q=1.0+(PlantLabelMaker.getQualityBonus()/100); if PlantLabelMaker.maker then q=q+(PlantLabelMaker.maker.skill/140) end; q=math.min(2.5,q); PlantLabelMaker.productStock[m.productType]=(PlantLabelMaker.productStock[m.productType] or 0)+m.quantity; PlantLabelMaker.totalProducts=PlantLabelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlantLabelMaker.maker then PlantLabelMaker.maker.itemsMade=PlantLabelMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PlantLabelMaker.maker.skill=math.min(100,PlantLabelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Oznaka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"plantlabel.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PlantLabelMaker.update(dt) if not _G.state then return end; PlantLabelMaker.dayTimer=PlantLabelMaker.dayTimer+dt; if PlantLabelMaker.dayTimer>=30 then PlantLabelMaker.dayTimer=0; for i=#PlantLabelMaker.activeMaking,1,-1 do local m=PlantLabelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlantLabelMaker.completeMaking(m); table.remove(PlantLabelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlantLabelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlantLabelMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlantLabelMaker.getStats() return {ironStock=PlantLabelMaker.ironStock,bronzeStock=PlantLabelMaker.bronzeStock,woodStock=PlantLabelMaker.woodStock,leatherStock=PlantLabelMaker.leatherStock,silverStock=PlantLabelMaker.silverStock,goldStock=PlantLabelMaker.goldStock,jewelStock=PlantLabelMaker.jewelStock,pearlStock=PlantLabelMaker.pearlStock,productStock=PlantLabelMaker.productStock,numBuildings=#PlantLabelMaker.buildings,hasMaker=PlantLabelMaker.maker~=nil,makerName=PlantLabelMaker.maker and PlantLabelMaker.maker.name or "—",makerSkill=PlantLabelMaker.maker and PlantLabelMaker.maker.skill or 0,activeMaking=#PlantLabelMaker.activeMaking,totalProducts=PlantLabelMaker.totalProducts} end
return PlantLabelMaker
